import{_ as t,a as r,o as a,a4 as o}from"./chunks/framework.-FZumj2l.js";const l=JSON.parse('{"title":"Create Draft Cart","description":"","frontmatter":{"outline":false,"apiType":"rest","examples":[{"id":"admin-customer-create-draft-cart","title":"Create Draft Cart","description":"Bootstrap an empty admin draft cart (`is_active = false`) for the given customer. Returns the `cartId` the admin uses for the rest of the Create-Order flow.","query":"curl -X POST \\"https://your-domain.com/api/admin/customers/7/draft-carts\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\" \\\\\\n  -H \\"Content-Type: application/json\\"\\n","variables":"{}\\n","response":"{\\n  \\"cartId\\": 412,\\n  \\"customerId\\": 7,\\n  \\"success\\": true,\\n  \\"message\\": \\"Draft cart created.\\"\\n}\\n","commonErrors":[{"error":"Not Found (404)","cause":"customerId in the URL does not match any customer","solution":"Verify the customer exists before calling this endpoint"},{"error":"Unprocessable Entity (422)","cause":"The underlying Cart::createCart facade refused (e.g. inactive channel)","solution":"Confirm a default channel + valid customer; review the error message"},{"error":"Unauthorized (401)","cause":"Missing or invalid admin Bearer token","solution":"Send a valid admin Bearer token (Integration token) in the Authorization header. See the Authentication page."}]}]},"headers":[],"relativePath":"api/rest-api/admin/customers/create-draft-cart.md","filePath":"api/rest-api/admin/customers/create-draft-cart.md","lastUpdated":1783327468000}'),d={name:"api/rest-api/admin/customers/create-draft-cart.md"};function s(n,e,i,c,h,p){return a(),r("div",null,e[0]||(e[0]=[o('<h1 id="create-draft-cart" tabindex="-1">Create Draft Cart <a class="header-anchor" href="#create-draft-cart" aria-label="Permalink to &quot;Create Draft Cart&quot;">​</a></h1><p>Starts a fresh Create-Order session by spawning an empty draft cart (<code>is_active = false</code>) bound to the given customer. This is the customer-nested counterpart to the <code>POST /api/admin/orders/{id}/reorder</code> action (which builds the cart from an existing order). Both flows produce the same kind of draft cart and end up at the cart-keyed write endpoints (<code>POST /api/admin/carts/{id}/items</code>, addresses, shipping, payment).</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Method</th></tr></thead><tbody><tr><td><code>/api/admin/customers/{customerId}/draft-carts</code></td><td>POST</td></tr></tbody></table><p>The customer is taken from the URL — the request body is empty.</p><h2 id="response-fields" tabindex="-1">Response Fields <a class="header-anchor" href="#response-fields" aria-label="Permalink to &quot;Response Fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>cartId</code></td><td>integer</td><td>The new draft cart&#39;s ID — use it for the rest of the Create-Order flow.</td></tr><tr><td><code>customerId</code></td><td>integer</td><td>The customer the cart belongs to.</td></tr><tr><td><code>success</code></td><td>boolean</td><td>Whether the cart was created.</td></tr><tr><td><code>message</code></td><td>string</td><td>Result message.</td></tr></tbody></table><h2 id="why-a-separate-endpoint-and-not-just-one-cart-create-route" tabindex="-1">Why a separate endpoint and not just one cart-create route <a class="header-anchor" href="#why-a-separate-endpoint-and-not-just-one-cart-create-route" aria-label="Permalink to &quot;Why a separate endpoint and not just one cart-create route&quot;">​</a></h2><p>The customer-nested URL keeps fresh Create-Order distinct from Reorder, which is important because the two have completely different inputs and side-effects. Reorder consumes an existing order id; this endpoint only needs the customer.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>For how the Create-Order helper panels fit together, see the <a href="./create-order-helpers/">Create-Order Helpers overview</a>.</p></div>',10)]))}const m=t(d,[["render",s]]);export{l as __pageData,m as default};
